"""Source-gated pedestrian route construction for C111329.

This module has no CARLA import at load time. The site packet must be measured
from the local map and device inspection before a Native actor is spawned.
"""
from __future__ import annotations

import hashlib
import json
import math
from dataclasses import dataclass


def digest(value: object) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("two-dimensional measured point required")
    p = tuple(float(x) for x in value)
    if not all(math.isfinite(x) for x in p):
        raise ValueError("nonfinite point")
    return p


def crossing_plan(site: dict, route_kind: str, authorization: bool) -> dict:
    """Build a complete curb-to-curb waypoint route using measured corners.

    site has four clockwise corner coordinates, map provenance, an intersection
    polygon and device inventory. A device's road-facing signal is insufficient.
    """
    if route_kind not in {"adjacent", "opposite"}:
        raise ValueError("unknown route kind")
    for key in ("map_name", "map_sha256", "survey_source", "intersection_polygon", "corners", "devices"):
        if not site.get(key):
            raise ValueError(f"missing site source: {key}")
    corners = [point(p) for p in site["corners"]]
    polygon = [point(p) for p in site["intersection_polygon"]]
    if len(corners) != 4 or len(polygon) < 4 or len(set(corners)) != 4:
        raise ValueError("four distinct corners and intersection polygon required")
    if route_kind == "adjacent":
        start, end = corners[0], corners[1]
    else:
        start, end = corners[0], corners[2]
    if math.dist(start, end) < 2:
        raise ValueError("crossing path too short")
    if authorization:
        supported = [d for d in site["devices"] if d.get("official_source") and d.get("pedestrian_governance") == "diagonal" and d.get("state") == "permissive" and d.get("instruction_source")]
        if not supported:
            raise ValueError("no source-backed official diagonal pedestrian authorization")
    else:
        supported = []
    path = [tuple(start[i] + (end[i] - start[i]) * t / 20 for i in range(2)) for t in range(21)]
    return {"map_name": site["map_name"], "map_sha256": site["map_sha256"], "survey_source": site["survey_source"], "route_kind": route_kind, "start": start, "end": end, "waypoints": path, "intersection_polygon": polygon, "device_inventory_sha256": digest(site["devices"]), "authorizing_device_ids": [d["id"] for d in supported], "exception_484B_290": "unresolved"}


def construct_walker(world, site: dict, route_kind: str, authorization: bool, blueprint_id: str):
    """Spawn a walker at measured corner and command the complete route.

    The adapter supplies location and route-driving methods to avoid a CARLA
    dependency during CPU tests. Actual path execution needs Native readback.
    """
    plan = crossing_plan(site, route_kind, authorization)
    if not blueprint_id.startswith("walker.pedestrian."):
        raise ValueError("walker blueprint required")
    walker = world.spawn_walker(blueprint_id, plan["start"])
    if walker is None:
        raise ValueError("walker spawn failed")
    try:
        world.drive_walker_route(walker, plan["waypoints"])
        if world.walker_id(walker) is None:
            raise ValueError("walker identity readback failed")
        return walker, plan
    except Exception:
        world.destroy_actor(walker)
        raise

"""Lazy, source-gated Native walker and four-camera adapter for C111329.

The reviewed site binder supplies an original device reader, an exact walker
blueprint and four already placed RGB sensors. This class controls the actor and
owns sensor listeners; the binder remains responsible for world restoration.
"""
from __future__ import annotations

import io
import math
from queue import Empty, Queue

from PIL import Image

CAMERAS = ('front', 'rear', 'left', 'right')


class CarlaCrossingAdapter:
    is_diagnostic = False

    def __init__(self, world, sensors, device_reader, *, blueprint_library,
                 location_factory, transform_factory, vector_factory,
                 walker_control_factory, spawn_z, speed_mps=1.2,
                 timeout_seconds=5.0):
        if set(sensors) != set(CAMERAS) or len(sensors) != 4:
            raise ValueError('four named original camera sensors required')
        if not callable(device_reader) or not all(callable(f) for f in
            (location_factory, transform_factory, vector_factory, walker_control_factory)):
            raise ValueError('Native source and CARLA factories required')
        if not math.isfinite(spawn_z) or not 0 < speed_mps <= 2.5:
            raise ValueError('source-bound walker height and speed required')
        self.world, self.sensors, self.device_reader = world, sensors, device_reader
        self.blueprints = blueprint_library
        self.location_factory, self.transform_factory = location_factory, transform_factory
        self.vector_factory, self.control_factory = vector_factory, walker_control_factory
        self.spawn_z, self.speed_mps, self.timeout_seconds = spawn_z, speed_mps, timeout_seconds
        self.queues = {name: Queue() for name in CAMERAS}
        self.listening = []
        self.route = None
        self.route_index = 0
        self.images = {}
        self.frame = None
        settings = world.get_settings()
        if settings.synchronous_mode is not True or abs(settings.fixed_delta_seconds - 0.05) > 1e-8:
            raise ValueError('synchronous original 20 Hz world required')
        try:
            for name in CAMERAS:
                sensor = sensors[name]
                sensor.listen(lambda image, camera=name: self.queues[camera].put(image))
                self.listening.append(sensor)
        except Exception:
            self.close()
            raise

    def spawn_walker(self, blueprint_id, xy):
        if not blueprint_id.startswith('walker.pedestrian.'):
            raise ValueError('pedestrian blueprint required')
        blueprint = self.blueprints.find(blueprint_id)
        location = self.location_factory(x=float(xy[0]), y=float(xy[1]), z=float(self.spawn_z))
        actor = self.world.try_spawn_actor(blueprint, self.transform_factory(location))
        if actor is None:
            raise ValueError('source-bound pedestrian spawn failed')
        self.actor = actor
        return actor

    def drive_walker_route(self, actor, route):
        if len(route) < 2:
            raise ValueError('complete pedestrian crossing route required')
        self.route = [tuple(map(float, p)) for p in route]
        self.route_index = 1

    def walker_id(self, actor):
        return actor.id

    def walker_xy(self, actor):
        location = actor.get_location()
        return (float(location.x), float(location.y))

    def _control(self, actor):
        if self.route is None:
            raise ValueError('pedestrian route not installed')
        x, y = self.walker_xy(actor)
        while self.route_index < len(self.route):
            goal = self.route[self.route_index]
            dx, dy = goal[0] - x, goal[1] - y
            distance = math.hypot(dx, dy)
            if distance > 0.35:
                vector = self.vector_factory(x=dx / distance, y=dy / distance, z=0.0)
                actor.apply_control(self.control_factory(direction=vector,
                                                         speed=self.speed_mps, jump=False))
                return
            self.route_index += 1
        self.stop_walker(actor)

    def tick(self):
        actor = getattr(self, 'actor', None)
        if actor is None:
            raise ValueError('Native pedestrian actor not owned')
        self._control(actor)
        frame = self.world.tick()
        snapshot = self.world.get_snapshot()
        if snapshot.frame != frame:
            raise ValueError('Native world snapshot frame differs')
        self.frame = frame
        self.images = {}
        for name in CAMERAS:
            try:
                image = self.queues[name].get(timeout=self.timeout_seconds)
            except Empty as exc:
                raise ValueError('Native original camera frame missing') from exc
            if image.frame != frame:
                raise ValueError('Native original camera frame mismatch')
            self.images[name] = image
        return {'original_frame': frame,
                'elapsed_seconds': float(snapshot.timestamp.elapsed_seconds)}

    def camera_frames(self):
        if self.frame is None or set(self.images) != set(CAMERAS):
            raise ValueError('Native original four-camera frame unavailable')
        return {name: image.frame for name, image in self.images.items()}

    def camera_png(self, camera, frame):
        if camera not in CAMERAS or frame != self.frame or camera not in self.images:
            raise ValueError('Native original camera image unavailable')
        image = self.images[camera]
        raw = bytes(image.raw_data)
        if len(raw) != image.width * image.height * 4:
            raise ValueError('Native original BGRA dimensions mismatch')
        rgb = Image.frombytes('RGBA', (image.width, image.height), raw, 'raw', 'BGRA').convert('RGB')
        stream = io.BytesIO()
        rgb.save(stream, format='PNG')
        return stream.getvalue()

    def read_devices(self):
        value = self.device_reader(self.world, self.frame)
        if not isinstance(value, list):
            raise ValueError('original official device readback missing')
        return value

    def stop_walker(self, actor):
        vector = self.vector_factory(x=0.0, y=0.0, z=0.0)
        actor.apply_control(self.control_factory(direction=vector, speed=0.0, jump=False))

    def destroy_actor(self, actor):
        try:
            actor.destroy()
        finally:
            self.close()

    def close(self):
        for sensor in self.listening:
            sensor.stop()
        self.listening.clear()

"""Independent original-frame crossing measurement; no legality evaluator."""
from __future__ import annotations

import math

from native_crossing import crossing_plan, digest, point
from native_acquisition import CAMERAS, _sha


def _cross(a, b, c):
    return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])


def inside_polygon(p, polygon):
    x, y = point(p)
    inside = False
    for a, b in zip(polygon, polygon[1:] + polygon[:1]):
        if abs(_cross(a, b, (x, y))) < 1e-9 and min(a[0], b[0]) <= x <= max(a[0], b[0]) and min(a[1], b[1]) <= y <= max(a[1], b[1]):
            return False
        if (a[1] > y) != (b[1] > y) and x < (b[0]-a[0])*(y-a[1])/(b[1]-a[1]) + a[0]:
            inside = not inside
    return inside


def measure(plan: dict, frames: list[dict], device_observations: list[dict]) -> dict:
    """Require original continuous frames, observed walker and device readback."""
    if len(frames) < 3 or not device_observations:
        raise ValueError("original walker and device histories required")
    indexes = [f["original_frame"] for f in frames]
    if any(b != a + 1 for a, b in zip(indexes, indexes[1:])):
        raise ValueError("noncontiguous original frames")
    ids = {f.get("walker_id") for f in frames}
    if None in ids or len(ids) != 1:
        raise ValueError("walker identity discontinuity")
    polygon = [point(p) for p in plan["intersection_polygon"]]
    actual = [point(f["walker_center_xy"]) for f in frames]
    if math.dist(actual[0], point(plan["start"])) > 1.5 or math.dist(actual[-1], point(plan["end"])) > 1.5:
        raise ValueError("crossing endpoints not observed")
    if not any(inside_polygon(p, polygon) for p in actual):
        raise ValueError("no intersection traversal observed")
    by_frame = {d["original_frame"]: d for d in device_observations}
    if any(i not in by_frame for i in indexes):
        raise ValueError("device history incomplete")
    if any(not by_frame[i].get("source_sha256") or not by_frame[i].get("official_source") for i in indexes):
        raise ValueError("official device source missing")
    authorized = all(by_frame[i].get("pedestrian_governance") == "diagonal" and by_frame[i].get("state") == "permissive" for i in indexes if inside_polygon(actual[indexes.index(i)], polygon))
    return {"original_frame_start": indexes[0], "original_frame_end": indexes[-1], "walker_id": next(iter(ids)), "observed_start_xy": actual[0], "observed_end_xy": actual[-1], "observed_inside_frames": sum(inside_polygon(p, polygon) for p in actual), "authorization_observed_during_inside": authorized, "device_source_hashes": sorted({by_frame[i]["source_sha256"] for i in indexes}), "route_kind_planned": plan["route_kind"], "exception_484B_290": "unresolved"}


def measure_acquisition(site: dict, packet: dict, *, case_id: str,
                        route_kind: str, authorization: bool,
                        expected_frames: int = 900, allow_diagnostic: bool = False) -> dict:
    """Saved-only join of the immutable site, Native rows and device history.

    A diagnostic packet is accepted only for explicit CPU fixture tests. The
    return is a physical observation summary, never a legal conclusion.
    """
    if packet.get("format") != "crossing-native-acquisition-v1" or packet.get("case_id") != case_id:
        raise ValueError("exact case Native acquisition mismatch")
    if packet.get("diagnostic") is not False and not allow_diagnostic:
        raise ValueError("diagnostic Native acquisition rejected for delivery")
    plan = crossing_plan(site, route_kind, authorization)
    if packet.get("site_sha256") != digest(site) or packet.get("plan_sha256") != _sha(plan):
        raise ValueError("saved site or route source hash mismatch")
    rows = packet.get("rows")
    if not isinstance(rows, list) or len(rows) != expected_frames or packet.get("frame_count") != expected_frames or packet.get("rows_sha256") != _sha(rows):
        raise ValueError("original Native rows missing or unsealed")
    if packet.get("fps") != 20 or packet.get("original_frame_start") != rows[0].get("original_frame") or packet.get("original_frame_end") != rows[-1].get("original_frame"):
        raise ValueError("original Native frame contract mismatch")
    device_ids = {d["id"] for d in site["devices"]}
    times = []
    walker_frames = []
    device_frames = []
    for row in rows:
        frame = row["original_frame"]
        times.append(row["elapsed_seconds"])
        if set(row.get("camera_frames", {})) != set(CAMERAS) or any(row["camera_frames"][name] != frame for name in CAMERAS):
            raise ValueError("saved four-camera original frame mismatch")
        devices = row.get("devices", [])
        if len(devices) != len(device_ids) or {d.get("id") for d in devices} != device_ids:
            raise ValueError("saved device inventory incomplete")
        for d in devices:
            original = next(item for item in site["devices"] if item["id"] == d["id"])
            if d.get("official_source") != original["official_source"] or d.get("instruction_source") != original["instruction_source"] or d.get("pedestrian_governance") != original.get("pedestrian_governance"):
                raise ValueError("saved device source changed")
            if not isinstance(d.get("source_sha256"), str) or len(d["source_sha256"]) != 64:
                raise ValueError("saved device readback source missing")
        chosen = next((d for d in devices if d["id"] in plan["authorizing_device_ids"]), devices[0])
        walker_frames.append({"original_frame": frame, "walker_id": row["walker_id"], "walker_center_xy": row["walker_center_xy"]})
        device_frames.append({"original_frame": frame, "source_sha256": chosen["source_sha256"],
                              "official_source": chosen["official_source"],
                              "pedestrian_governance": chosen["pedestrian_governance"], "state": chosen["state"]})
    if any(not math.isfinite(t) for t in times) or any(abs((b - a) - 0.05) > 0.002 for a, b in zip(times, times[1:])):
        raise ValueError("saved Native time discontinuity")
    result = measure(plan, walker_frames, device_frames)
    result.update({"case_id": case_id, "site_sha256": packet["site_sha256"],
                   "native_rows_sha256": packet["rows_sha256"],
                   "camera_frames_verified": True, "diagnostic": packet.get("diagnostic")})
    return result

"""Saved-only full PNG audit for original pedestrian crossing frames.

The caller supplies an actual capture directory and a manifest produced from that
capture. This checker never substitutes diagnostic images for physical evidence.
"""
from __future__ import annotations

import hashlib
import io
from pathlib import Path

from PIL import Image

from native_acquisition import CAMERAS, _sha


def inventory_camera_sources(packet: dict, capture_root: Path) -> dict:
    """Describe the four original PNG streams without changing captured bytes.

    The Native writer must save ``<camera>/<original_frame:06d>.png`` beneath
    its capture root. The independent auditor reopens these same paths.
    """
    if packet.get("format") != "crossing-native-acquisition-v1" or packet.get("rows_sha256") != _sha(packet.get("rows")):
        raise ValueError("unsealed Native acquisition rows")
    root = capture_root.resolve(strict=True)
    sources = []
    for row in packet["rows"]:
        frame = row["original_frame"]
        for camera in CAMERAS:
            rel = f"{camera}/{frame:06d}.png"
            path = (root / rel).resolve(strict=True)
            if not path.is_relative_to(root) or not path.is_file():
                raise ValueError("original camera PNG missing")
            sha = hashlib.sha256(path.read_bytes()).hexdigest()
            if row.get("camera_png_sha256") and row["camera_png_sha256"].get(camera) != sha:
                raise ValueError("original camera PNG differs from Native source hash")
            sources.append({"original_frame": frame, "camera": camera,
                            "path": rel, "sha256": sha})
    return {"format": "crossing-original-camera-png-v1", "case_id": packet["case_id"],
            "native_rows_sha256": packet["rows_sha256"], "sources": sources}


def audit_camera_sources(packet: dict, manifest: dict, capture_root: Path,
                         *, allow_diagnostic: bool = False) -> dict:
    if packet.get("format") != "crossing-native-acquisition-v1":
        raise ValueError("Native acquisition packet required")
    if packet.get("diagnostic") is not False and not allow_diagnostic:
        raise ValueError("diagnostic Native acquisition rejected for delivery")
    rows = packet.get("rows")
    if not isinstance(rows, list) or not rows or packet.get("rows_sha256") != _sha(rows):
        raise ValueError("unsealed Native acquisition rows")
    if packet.get("frame_count") != len(rows):
        raise ValueError("Native acquisition frame count mismatch")
    if manifest.get("format") != "crossing-original-camera-png-v1":
        raise ValueError("original camera manifest required")
    if manifest.get("case_id") != packet.get("case_id") or manifest.get("native_rows_sha256") != packet["rows_sha256"]:
        raise ValueError("camera manifest Native source binding mismatch")
    sources = manifest.get("sources")
    if not isinstance(sources, list) or len(sources) != len(rows) * len(CAMERAS):
        raise ValueError("four-camera original PNG source count mismatch")
    root = capture_root.resolve(strict=True)
    expected = {(row["original_frame"], camera) for row in rows for camera in CAMERAS}
    actual = [(source.get("original_frame"), source.get("camera")) for source in sources]
    if len(set(actual)) != len(actual) or set(actual) != expected:
        raise ValueError("four-camera original frame coverage mismatch")
    by_frame = {row["original_frame"]: row for row in rows}
    dimensions = {}
    pixel_sha256 = hashlib.sha256()
    for source in sources:
        frame, camera = source["original_frame"], source["camera"]
        if by_frame[frame].get("camera_frames", {}).get(camera) != frame:
            raise ValueError("camera PNG original frame join mismatch")
        native_png_hash = by_frame[frame].get("camera_png_sha256", {}).get(camera)
        if not allow_diagnostic and native_png_hash is None:
            raise ValueError("Native camera PNG source hash missing")
        rel = source.get("path")
        if not isinstance(rel, str) or not rel or Path(rel).is_absolute():
            raise ValueError("camera PNG relative path required")
        path = (root / rel).resolve(strict=True)
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError("camera PNG outside capture root")
        raw = path.read_bytes()
        sha = hashlib.sha256(raw).hexdigest()
        if sha != source.get("sha256"):
            raise ValueError("camera PNG source hash mismatch")
        if native_png_hash is not None and sha != native_png_hash:
            raise ValueError("camera PNG differs from Native source hash")
        try:
            with Image.open(io.BytesIO(raw)) as image:
                if image.format != "PNG":
                    raise ValueError("camera source is not PNG")
                image.load()
                rgb = image.convert("RGB")
                width, height = rgb.size
                pixels = rgb.tobytes()
        except (OSError, ValueError) as exc:
            raise ValueError("camera PNG full decode failed") from exc
        if width < 2 or height < 2 or not pixels:
            raise ValueError("camera PNG pixels or dimensions invalid")
        if camera in dimensions and dimensions[camera] != [width, height]:
            raise ValueError("camera PNG dimensions changed")
        dimensions[camera] = [width, height]
        pixel_sha256.update(f"{frame}:{camera}:".encode())
        pixel_sha256.update(pixels)
    return {"format": "crossing-camera-full-decode-receipt-v1",
            "case_id": packet["case_id"], "native_rows_sha256": packet["rows_sha256"],
            "source_manifest_sha256": _sha(manifest), "frame_count": len(rows),
            "decoded_png_count": len(sources), "camera_dimensions": dimensions,
            "decoded_pixel_sha256": pixel_sha256.hexdigest(),
            "diagnostic": packet.get("diagnostic")}

"""Reject incomplete or confounded saved crossing comparisons."""

FIXED = ("map_sha256", "intersection_polygon", "walker_blueprint_id", "camera_contract_sha256", "duration_frames", "fps")


def audit(left: dict, right: dict, comparison: str) -> dict:
    if comparison not in {"diagonal_path_without_authority", "diagonal_device_authority", "authorized_device_path_control"}:
        raise ValueError("unknown comparison")
    for case in (left, right):
        for field in (*FIXED, "original_measurement", "device_inventory_sha256"):
            if field not in case or case[field] in (None, ""):
                raise ValueError(f"missing source-bound comparison field: {field}")
        if case["fps"] != 20 or case["duration_frames"] < 2:
            raise ValueError("capture contract mismatch")
        if not case["original_measurement"].get("walker_id") or not case["original_measurement"].get("device_source_hashes"):
            raise ValueError("original walker/device source missing")
    for field in FIXED:
        if left[field] != right[field]:
            raise ValueError(f"fixed condition differs: {field}")
    if comparison == "diagonal_device_authority":
        if left["route_kind"] != right["route_kind"] or left["route_kind"] != "opposite":
            raise ValueError("device comparison route changed")
        if left["authorization_observed"] == right["authorization_observed"]:
            raise ValueError("device authorization did not vary")
    else:
        if left["device_inventory_sha256"] != right["device_inventory_sha256"] or left["authorization_observed"] != right["authorization_observed"]:
            raise ValueError("route comparison device condition changed")
        if left["route_kind"] == right["route_kind"]:
            raise ValueError("route kind did not vary")
    return {"comparison_id": comparison, "passed": True, "case_ids": [left["case_id"], right["case_id"]]}


def audit_saved_pair(left_attempt, left_refs, right_attempt, right_refs, comparison, *, expected_frames=900, allow_diagnostic=False):
    """Reopen two original attempts and require the exact planned contrast."""
    import hashlib
    import json
    from pathlib import Path
    from delivery_audit import audit as audit_delivery
    from saved_process import ASSIGNMENT, CASES, _read

    expected = {
        'diagonal_path_without_authority': ('adjacent_no_diagonal_authority', 'diagonal_no_authority'),
        'diagonal_device_authority': ('diagonal_no_authority', 'diagonal_authorized'),
        'authorized_device_path_control': ('diagonal_authorized', 'adjacent_authorized_device'),
    }
    if comparison not in expected:
        raise ValueError('unknown exact C111329 comparison')
    if len(left_refs) != 4 or len(right_refs) != 4:
        raise ValueError('site, Native, camera and saved source references required')
    case_ids = [ASSIGNMENT + '__' + suffix for suffix in expected[comparison]]
    roots = [Path(left_attempt).resolve(strict=True), Path(right_attempt).resolve(strict=True)]
    refs = [left_refs, right_refs]
    audits = [audit_delivery(root, case_id, *source_refs, expected_frames=expected_frames, allow_diagnostic=allow_diagnostic) for root, case_id, source_refs in zip(roots, case_ids, refs)]
    sites = [_read(root, source_refs[0]) for root, source_refs in zip(roots, refs)]
    natives = [_read(root, source_refs[1]) for root, source_refs in zip(roots, refs)]
    saved = [_read(root, source_refs[3]) for root, source_refs in zip(roots, refs)]
    for i in range(2):
        if audits[i]['case_id'] != case_ids[i] or (audits[i]['diagnostic'] is not False and not allow_diagnostic):
            raise ValueError('comparison requires exact original Native deliveries')
        if saved[i]['measurement']['route_kind_planned'] != CASES[expected[comparison][i]][0]:
            raise ValueError('measured crossing route differs from planned case')
    if (sites[0]['map_sha256'] != sites[1]['map_sha256'] or
            sites[0]['intersection_polygon'] != sites[1]['intersection_polygon'] or
            sites[0]['corners'] != sites[1]['corners']):
        raise ValueError('fixed intersection geometry differs')
    if (audits[0]['frame_count'] != audits[1]['frame_count'] or
            saved[0]['media_audit']['camera_dimensions'] != saved[1]['media_audit']['camera_dimensions']):
        raise ValueError('fixed capture contract differs')
    if comparison == 'diagonal_device_authority':
        if (natives[0]['device_inventory_sha256'] == natives[1]['device_inventory_sha256'] or
                saved[0]['measurement']['authorization_observed_during_inside'] is True or
                saved[1]['measurement']['authorization_observed_during_inside'] is not True):
            raise ValueError('source-measured diagonal authorization contrast missing')
    else:
        if (natives[0]['device_inventory_sha256'] != natives[1]['device_inventory_sha256'] or
                saved[0]['measurement']['authorization_observed_during_inside'] !=
                saved[1]['measurement']['authorization_observed_during_inside']):
            raise ValueError('fixed official device source or state differs')
